style.css:
@-moz-document domain("roblox.com") {
/* Changes the main site background */
  .content-wrapper, .nano-content {
    background-image: url(https://i.pinimg.com/1200x/58/1d/e8/581de82a20db0399fee2dfbae606b64c.jpg) !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
  }

  /* Makes the sidebar and header slightly see-through so your background shows */
  .menu-vertical, .rbx-header, .content-header {
    background: rgba(255, 255, 255, 0.5) !important; 
  }
}
